 "content": "from collections import Counter


def _mode(row):
    return Counter(row).most_common(1)[0][0]


def transform(grid):
    h, w = len(grid), len(grid[0])
    row_modes = [_mode(row) for row in grid]
    col_modes = [_mode([grid[r][c] for r in range(h)]) for c in range(w)]
    common_row_mode = Counter(row_modes).most_common(1)[0][0]
    common_col_mode = Counter(col_modes).most_common(1)[0][0]
    hr = [r for r, m in enumerate(row_modes) if m != common_row_mode]
    vc = [c for c, m in enumerate(col_modes) if m != common_col_mode]
    if len(hr) < 2 or len(vc) < 2:
        raise ValueError('Could not identify at least two lattice boundary lines')

    # Each output cell is the area between adjacent horizontal/vertical lattice
    # lines. Matching non-background colors at all four intersections fill it;
    # otherwise it retains the interior tile color.
    interior = Counter(v for row in grid for v in row).most_common(1)[0][0]
    line_color = common_row_mode
    out = []
    for r0, r1 in zip(hr, hr[1:]):
        row = []
        for c0, c1 in zip(vc, vc[1:]):
            corners = (grid[r0][c0], grid[r0][c1], grid[r1][c0], grid[r1][c1])
            v = corners[0]
            row.append(v if v != line_color and all(x == v for x in corners) else interior)
        out.append(row)

    # The outer portions of the lattice can be padding. Remove only wholly
    # interior-color rows/columns, retaining the marked rectangular region.
    while out and all(v == interior for v in out[0]):
        out.pop(0)
    while out and all(v == interior for v in out[-1]):
        out.pop()
    while out and all(row[0] == interior for row in out):
        for row in out:
            row.pop(0)
    while out and all(row[-1] == interior for row in out):
        for row in out:
            row.pop()
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
